@ControllerAdvice
public class GlobalExceptionHandler {
    @ExceptionHandler(AuthenticationException.class)
    public ResponseEntity<String> handleAuthError(AuthenticationException e) {
        return ResponseEntity.status(401).body("Unauthorized");
    }
}

public void processUserData() {
    // Main Thread: User is authenticated
    Authentication auth = SecurityContextHolder.getContext().getAuthentication();
    System.out.println("User: " + auth.getName()); // Prints: UserA

    completableFuture.runAsync(() -> {
        // Child Thread
        Authentication asyncAuth = SecurityContextHolder.getContext().getAuthentication();
        System.out.println("Async User: " + (asyncAuth != null ? asyncAuth.getName() : "null"));
    });
}

